-- Contenido del glosario: 189 palabras del material actual, con su traduccion.
--
-- Seleccion: todos los phrasal verbs (en su forma completa, verbo + particula)
-- y conectores que detecta el analizador, mas el vocabulario de dificultad 3-5
-- cuya forma base no figure en las listas de palabras comunes.
--
-- Ese ultimo filtro evita tarjetas inutiles como "working" o "started": salian
-- marcadas solo porque la forma conjugada no esta en las listas, aunque el
-- verbo sea de los mas comunes. Ademas se descarto a mano una veintena
-- demasiado facil para merecer tarjeta (ready, coffee, worst...).
--
-- ON CONFLICT DO NOTHING: idempotente, y no pisa nada que corrijas a mano.


DO $$
DECLARE n INTEGER;
BEGIN
    SELECT COUNT(*) INTO n FROM glossary;
    RAISE NOTICE 'glosario: % palabras', n;
END $$;
